(function(){
  if (window.__satInstalled__) return;
  window.__satInstalled__ = true;
  var canvas = document.getElementById('satCanvas');
  var ctx = canvas.getContext('2d');
  var hSlider = document.getElementById('hSlider');
  var hVal = document.getElementById('hVal');
  var vSlider = document.getElementById('vSlider');
  var vVal = document.getElementById('vVal');
  var out = document.getElementById('satOut');
  var playBtn = document.getElementById('playBtn');
  var GM = 3.986e5, Re = 6371;
  var running = false, theta = 0;
  window.simState = { h: 700, v: 8, vCirc: 0, vEsc: 0, e: 0, a: 0, p: 0, status: '', running: false, angle: 0 };
  function compute(){
    var h = parseFloat(hSlider.value), v = parseFloat(vSlider.value);
    var r0 = Re + h;
    var vCirc = Math.sqrt(GM / r0);
    var vEsc = Math.sqrt(2 * GM / r0);
    var hspec = r0 * v;
    var aInv = 2 / r0 - (v * v) / GM;
    var a = aInv > 0 ? 1 / aInv : -1 / Math.abs(aInv);
    var p = (hspec * hspec) / GM;
    var e = a > 0 ? Math.sqrt(Math.max(0, 1 - p / a)) : Math.sqrt(1 + p / Math.abs(a));
    var status;
    if (e < 0.02 && a > 0) status = 'مدار دائري';
    else if (a > 0) {
      var rmin = p / (1 + e);
      status = rmin < Re ? 'مسار هابط (يصطدم بالأرض)' : 'مدار إهليلجي';
    } else status = 'مسار فتحي (هروب من الجاذبية)';
    window.simState.h = h; window.simState.v = v; window.simState.vCirc = vCirc;
    window.simState.vEsc = vEsc; window.simState.e = e; window.simState.a = a; window.simState.p = p;
    window.simState.status = status;
    return { h: h, v: v, r0: r0, vCirc: vCirc, vEsc: vEsc, e: e, a: a, p: p, status: status };
  }
  function draw(){
    var s = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var cx = canvas.width / 2, cy = canvas.height / 2;
    var maxR = s.e < 1 ? Math.min(s.p / (1 - s.e), s.r0 * 3.5) : s.r0 * 3.5;
    var k = (Math.min(canvas.width, canvas.height) / 2 - 50) / maxR;
    var er = Math.max(Re * k, 16);
    ctx.fillStyle = '#0ea5e9';
    ctx.beginPath(); ctx.arc(cx, cy, er, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#16a34a';
    ctx.beginPath(); ctx.arc(cx, cy, er * 0.55, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(cx, cy, er, 0, Math.PI * 2); ctx.stroke();
    var orbitColor = '#22c55e';
    if (s.status.indexOf('إهليلجي') >= 0) orbitColor = '#f59e0b';
    else if (s.status.indexOf('هابط') >= 0) orbitColor = '#ef4444';
    else if (s.status.indexOf('فتحي') >= 0) orbitColor = '#3b82f6';
    ctx.strokeStyle = orbitColor; ctx.lineWidth = 2;
    ctx.setLineDash([6, 4]);
    ctx.beginPath();
    var started = false;
    if (s.e < 1) {
      for (var i = 0; i <= 360; i++) {
        var th = (i / 360) * Math.PI * 2;
        var r = s.p / (1 + s.e * Math.cos(th));
        var px = cx + r * k * Math.cos(th);
        var py = cy + r * k * Math.sin(th);
        if (!started) { ctx.moveTo(px, py); started = true; } else ctx.lineTo(px, py);
      }
    } else {
      var lim = Math.acos(-1 / s.e);
      for (var j = 0; j <= 120; j++) {
        var th2 = -lim + (j / 120) * 2 * lim;
        var r2 = s.p / (1 + s.e * Math.cos(th2));
        var px2 = cx + r2 * k * Math.cos(th2);
        var py2 = cy + r2 * k * Math.sin(th2);
        if (!started) { ctx.moveTo(px2, py2); started = true; } else ctx.lineTo(px2, py2);
      }
    }
    ctx.stroke();
    ctx.setLineDash([]);
    var rr = s.e < 1 ? s.p / (1 + s.e * Math.cos(theta)) : s.p / (1 + s.e * Math.cos(theta));
    var sx = cx + rr * k * Math.cos(theta);
    var sy = cy + rr * k * Math.sin(theta);
    ctx.fillStyle = '#facc15';
    ctx.beginPath(); ctx.arc(sx, sy, 5, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(sx, sy, 5, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = '#e2e8f0'; ctx.font = '11px sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText('الأرض', cx + er + 6, cy + er + 2);
    ctx.textAlign = 'right';
    ctx.fillText('v₀ الدائرية = ' + s.vCirc.toFixed(1) + ' km/s', canvas.width - 8, 8);
    ctx.fillText('v₀ الهروب = ' + s.vEsc.toFixed(1) + ' km/s', canvas.width - 8, 22);
    hVal.textContent = s.h;
    vVal.textContent = s.v.toFixed(1);
    out.textContent = s.status + ' | e = ' + s.e.toFixed(2) + ' | v الدائرية = ' + s.vCirc.toFixed(1) + ' km/s | v الهروب = ' + s.vEsc.toFixed(1) + ' km/s';
    window.simState.angle = theta;
  }
  playBtn.addEventListener('click', function(){
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل';
  });
  hSlider.addEventListener('input', function(){});
  vSlider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){
    if (running) {
      var s = compute();
      var r = s.p / (1 + s.e * Math.cos(theta));
      var dth = 0.008 * (s.r0 / Math.max(r, 1));
      theta += dth;
      if (s.e >= 1) {
        var lim = Math.acos(-1 / s.e);
        theta = Math.max(-lim + 0.06, Math.min(lim - 0.06, theta));
      }
    }
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
